llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C29"],
      "claim": "Verapamil, a close structural analogue with two dimethoxyphenyl groups and a basic tertiary amine, has an absolute oral bioavailability of 34% in humans, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Noscapine, a dimethoxyisoquinoline alkaloid with a basic amine and a lactone, has an absolute oral bioavailability of 30% in healthy volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C41"],
      "claim": "Donepezil, a dimethoxyindanone with a basic amine, has complete oral bioavailability (100%) in humans, indicating that this chemotype can achieve high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "Tetrabenazine, a dimethoxy-tetrahydroisoquinoline with a ketone, has very low oral systemic availability (0.049), but this is driven by rapid ketone reduction, a metabolic liability not present in the query's lactam; transferability is low.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C67"],
      "claim": "One verapamil study reported mean bioavailability of 19.4%, slightly below the 20% threshold, illustrating borderline first-pass metabolism in this structural class.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest structural analogues (verapamil, noscapine, donepezil) show absolute oral bioavailability at or above 20%, while the very low F of tetrabenazine is tied to a ketone reduction liability absent in the query's lactam; therefore high F is better supported.",
  "evidence_gaps": [
    "No direct pharmacokinetic data for the query molecule.",
    "The lactam versus ketone/nitrile structural differences may alter first-pass metabolism unpredictably.",
    "Low neutral fraction (0.02) and high basic pKa may reduce passive permeability; actual intestinal permeability is unknown.",
    "No data on metabolic stability or transporter involvement."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

